30	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
31	            throws MissingOwnerFieldsException {
32	        List<String> missing = new ArrayList<>();
33	        if (isBlank(request.getFirstName())) {
34	            missing.add("firstName");
35	        }
36	        if (isBlank(request.getLastName())) {
37	            missing.add("lastName");
38	        }
39	        // Address may be supplied in a structured form (addressLine1 + optional addressLine2) or
40	        // as the flat 'address' (kept for backward compatibility). The structured form is preferred
41	        // whenever a non-blank addressLine1 is present; otherwise the flat address is used. Each
42	        // supplied field is normalised (trim/collapse/upper-case/expand abbreviations) and the
43	        // required-field check runs against that form, so a value blank only once normalised is
44	        // rejected. The canonical, composed value is written back onto 'address' in place, so it is
45	        // what gets stored and returned and what everything downstream reads — the household hash,
46	        // postcode validation and locality all see the structured-derived value, falling back to the
47	        // flat address when no structured fields were given.
48	        String normalizedLine1 = OwnerAddress.normalize(request.getAddressLine1());
49	        if (!normalizedLine1.isEmpty()) {
50	            String normalizedLine2 = OwnerAddress.normalize(request.getAddressLine2());
51	            request.setAddressLine1(normalizedLine1);
52	            request.setAddressLine2(normalizedLine2.isEmpty() ? null : normalizedLine2);
53	            request.setAddress(OwnerAddress.compose(normalizedLine1, normalizedLine2));
54	        }
55	        else {
56	            String normalizedAddress = OwnerAddress.normalize(request.getAddress());
57	            if (normalizedAddress.isEmpty()) {
58	                missing.add("address");
59	            }
60	            else {
61	                request.setAddress(normalizedAddress);
62	            }
