65	            missing.add("city");
66	        }
67	        if (isBlank(request.getTelephone())) {
68	            missing.add("telephone");
69	        }
70	        if (!missing.isEmpty()) {
71	            throw new MissingOwnerFieldsException(missing);
72	        }
73	        validated.set(request);
74	    }
75	
76	    private static boolean isBlank(String value) {
77	        return value == null || value.isBlank();
78	    }
79	}
